package kernels

// The assembly of this package is the GEMM micro-kernels only, generated by
// go-asmgen (the generators are a separate module, asmgen/). The output keeps
// the sum_<arch>.s names go-ndarray/ndarray gave it; ndarray's files also hold
// non-GEMM kernels, and asmgen/splitdiff proves these are exactly their GEMM
// part. `go generate` regenerates every architecture, whatever the host;
// `cd asmgen && go run ./regen` does the same without the shell.
//
//go:generate sh -c "cd asmgen/amd64 && GOFLAGS=-mod=mod go run gen.go && mv sum_amd64.s ../../sum_amd64.s"
//go:generate sh -c "cd asmgen/arm64 && GOFLAGS=-mod=mod go run gen.go && mv sum_arm64.s ../../sum_arm64.s"
//go:generate sh -c "cd asmgen/loong64 && go run . && mv sum_loong64.s ../../sum_loong64.s"
//go:generate sh -c "cd asmgen/ppc64le && go run . && mv sum_ppc64le.s ../../sum_ppc64le.s"
//go:generate sh -c "cd asmgen/riscv64 && go run . && mv sum_riscv64.s ../../sum_riscv64.s"
//go:generate sh -c "cd asmgen/s390x && go run . && mv sum_s390x.s ../../sum_s390x.s"
